<template><view class="page" v-if="authorized"><view class="hero"><text class="title">{{ readOnly ? '查看' : (id ? '编辑' : '新增') }}销售政策</text><text class="subtitle">政策编号由服务端自动生成，套餐档位按本次政策独立保存</text></view><view class="card"><view class="field"><text>政策编号</text><view class="readonly">{{ form.policyNo || '保存后自动生成' }}</view></view><view class="field"><text>政策名称</text><input v-model="form.policyName" :disabled="readOnly" placeholder="例如：石斛六月销售政策" /></view><view class="field"><text>核算周期</text><picker :disabled="readOnly" :range="periods" range-key="label" :value="periodIndex" @change="selectPeriod"><view class="control">{{ periods[periodIndex]?.label || '请选择当前机构核算周期' }}</view></picker></view><view class="field"><text>商品</text><picker :disabled="readOnly" :range="products" range-key="productName" :value="productIndex" @change="selectProduct"><view class="control">{{ products[productIndex]?.productName || '请选择商品' }}</view></picker></view></view><view class="card"><view class="section-head"><text>套餐档位</text><button v-if="!readOnly" @tap="addTier">＋添加档位</button></view><view class="tier" v-for="(tier,index) in form.packages" :key="index"><view class="tier-head"><text>档位 {{ index + 1 }}</text><button v-if="!readOnly" @tap="removeTier(index)">删除</button></view><input v-model="tier.packageName" :disabled="readOnly" placeholder="档位名称，例如：5盒" /><view class="tier-grid"><view><text>购买数量</text><input v-model="tier.purchaseQuantity" :disabled="readOnly" type="digit" placeholder="0.000" @input="limit(tier,'purchaseQuantity',$event.detail.value,3)" /></view><view><text>赠送数量</text><input v-model="tier.giftQuantity" :disabled="readOnly" type="digit" placeholder="0.000" @input="limit(tier,'giftQuantity',$event.detail.value,3)" /></view><view><text>套餐价</text><input v-model="tier.packagePrice" :disabled="readOnly" type="digit" placeholder="0.00" @input="limit(tier,'packagePrice',$event.detail.value,2)" /></view></view></view><view class="empty-inline" v-if="!form.packages.length">请添加至少一个套餐档位；零散购买不在此处配置。</view></view><view class="footer"><button @tap="back">返回</button><button v-if="!readOnly" class="primary" @tap="save">保存政策</button></view></view></template>
<script>
import { request } from '@/api/index.js'; import { hasActionPermission, requireModulePermission } from '@/utils/permission.js'; import { workContext } from '@/utils/workContext.js'
export default { data(){return{authorized:false,id:'',readOnly:false,deptId:'',products:[],periods:[],form:{policyNo:'',policyName:'',periodId:'',productId:'',status:'1',packages:[]}}}, computed:{periodIndex(){const i=this.periods.findIndex(x=>String(x.periodId)===String(this.form.periodId));return i<0?0:i},productIndex(){const i=this.products.findIndex(x=>String(x.productId)===String(this.form.productId));return i<0?0:i}}, onLoad(o){this.id=o.id||'';this.readOnly=o.mode==='view';this.authorized=requireModulePermission('campaignPolicy')&&(this.readOnly?hasActionPermission('campaignPolicy','query'):hasActionPermission('campaignPolicy',this.id?'edit':'add'));const s=workContext.snapshot();this.deptId=s.currentDeptId;if(this.authorized)this.init()}, methods:{unwrap(r){return r?.rows||r?.data?.rows||r?.data||[]},date(v){return v?String(v).replace('T',' ').slice(0,19):'-'},async init(){const [p,a]=await Promise.all([request({url:'/finance/product/list',method:'GET',data:{pageNum:1,pageSize:200,deptId:this.deptId}}),request({url:'/finance/accountingPeriod/list',method:'GET',data:{pageNum:1,pageSize:200,deptId:this.deptId}})]);this.products=this.unwrap(p);this.periods=this.unwrap(a).filter(x=>String(x.deptId)===String(this.deptId)).map(x=>({...x,label:`${x.periodNo||x.periodId}（${this.date(x.startTime)} 至 ${x.endTime?this.date(x.endTime):'当前'}）`}));if(this.id){const r=await request({url:`/member/campaign/policy/${this.id}`,method:'GET'});const d=r.data||r;this.form={...this.form,...d,packages:(d.packages||[]).map(x=>({...x}))}}},selectPeriod(e){this.form.periodId=this.periods[Number(e.detail.value)]?.periodId||''},selectProduct(e){this.form.productId=this.products[Number(e.detail.value)]?.productId||''},addTier(){this.form.packages.push({packageName:'',purchaseQuantity:'',giftQuantity:'',packagePrice:'',sortNo:this.form.packages.length+1})},removeTier(i){this.form.packages.splice(i,1)},limit(obj,key,value,precision){let s=String(value||'').replace(/[^\d.]/g,'').replace(/\.(?=.*\.)/g,'');obj[key]=s.includes('.')?s.split('.')[0]+'.'+s.split('.')[1].slice(0,precision):s},async save(){if(!this.form.policyName||!this.form.periodId||!this.form.productId)return uni.showToast({title:'请填写政策名称、核算周期和商品',icon:'none'});if(!this.form.packages.length)return uni.showToast({title:'请至少添加一个套餐档位',icon:'none'});for(const p of this.form.packages){if(!p.packageName||!(Number(p.purchaseQuantity)>0)||Number(p.giftQuantity)<0||!(Number(p.packagePrice)>0))return uni.showToast({title:'请完整填写套餐档位，数量3位小数、金额2位小数',icon:'none'});p.totalQuantity=Number(p.purchaseQuantity)+Number(p.giftQuantity)}const body={...this.form,packages:this.form.packages.map((p,i)=>({...p,sortNo:i+1}))};await request({url:this.id?`/member/campaign/policy/${this.id}`:'/member/campaign/policy',method:this.id?'PUT':'POST',data:body});uni.showToast({title:'销售政策已保存',icon:'success'});setTimeout(()=>this.back(),400)},back(){uni.navigateBack()}}
}
</script>
<style scoped>.page{min-height:100vh;background:#f4f7fb;padding:24rpx 24rpx 150rpx}.hero{padding:30rpx;background:linear-gradient(135deg,#0b74de,#1456b8);border-radius:22rpx;color:#fff}.title{display:block;font-size:38rpx;font-weight:700}.subtitle{display:block;margin-top:10rpx;font-size:23rpx;opacity:.85}.card{background:#fff;border-radius:18rpx;padding:24rpx;margin:18rpx 0;box-shadow:0 8rpx 24rpx rgba(15,23,42,.06)}.field{margin:14rpx 0}.field>text,.tier-grid text{display:block;color:#475569;font-size:24rpx;margin-bottom:8rpx}.field input,.tier input{box-sizing:border-box;width:100%;padding:20rpx;border:1rpx solid #dce5f0;border-radius:12rpx;background:#fff}.readonly,.control{padding:20rpx;border:1rpx solid #dce5f0;border-radius:12rpx;background:#f8fafc;color:#64748b}.section-head,.tier-head{display:flex;justify-content:space-between;align-items:center;font-weight:700}.section-head button,.tier-head button{border:0;background:#eef4fb;color:#0b74de;padding:8rpx 16rpx;border-radius:10rpx;font-size:23rpx}.tier{margin-top:16rpx;padding:18rpx;border:1rpx solid #e2e8f0;border-radius:14rpx}.tier-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12rpx;margin-top:14rpx}.empty-inline{padding:20rpx 0;color:#94a3b8;font-size:23rpx}.footer{position:fixed;bottom:0;left:0;right:0;display:flex;gap:16rpx;padding:20rpx 24rpx calc(20rpx + env(safe-area-inset-bottom));background:#fff;box-shadow:0 -6rpx 20rpx rgba(15,23,42,.08)}.footer button{flex:1;border:0;border-radius:12rpx;background:#eef3f8;color:#334155}.footer .primary{background:#0b74de;color:#fff}</style>
